@namespace sv_61f065cf9e9049188e7418691eccd5b2.Components.Pages.Settings

<nav class="nav nav-pills flex-column" role="tablist">
    @foreach (var section in Sections)
    {
        <button class="nav-link text-start @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionChanged.InvokeAsync(section)"
                role="tab">
            <i class="@GetIcon(section) me-2"></i>@section
        </button>
    }
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "bi bi-person",
        "Notifications" => "bi bi-bell",
        "Security" => "bi bi-shield-lock",
        "Appearance" => "bi bi-palette",
        _ => "bi bi-gear"
    };
}

@namespace sv_61f065cf9e9049188e7418691eccd5b2.Components.Pages.Settings
@using sv_61f065cf9e9049188e7418691eccd5b2.Services
@inject ISettingsService SettingsService

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">Profile Settings</h4>

        @if (_loading)
        {
            <div class="spinner-border" role="status"><span class="visually-hidden">Loading...</span></div>
        }
        else
        {
            @if (!string.IsNullOrEmpty(_message))
            {
                <div class="alert alert-success alert-dismissible fade show" role="alert">
                    @_message
                    <button type="button" class="btn-close" @onclick="() => _message = null"></button>
                </div>
            }

            <div class="row mb-4">
                <div class="col-md-3 text-center">
                    <img src="@_avatarUrl" alt="Avatar" class="rounded-circle img-thumbnail mb-2" style="width:120px;height:120px;object-fit:cover;" />
                    <p class="text-muted small text-break">@_avatarUrl</p>
                </div>
                <div class="col-md-9">
                    <div class="mb-3">
                        <label class="form-label">Display Name</label>
                        <input type="text" class="form-control" @bind="_displayName" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Email</label>
                        <input type="email" class="form-control" @bind="_email" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Bio</label>
                        <textarea class="form-control" rows="3" @bind="_bio"></textarea>
                    </div>
                </div>
            </div>

            <div class="d-flex gap-2">
                <button class="btn btn-primary" @onclick="SaveAsync">Save Changes</button>
                <button class="btn btn-outline-secondary" @onclick="DiscardChanges">Discard Changes</button>
            </div>
        }
    </div>
</div>

@code {
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";
    private string? _message;
    private bool _loading = true;
    private UserProfile? _savedProfile;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfileAsync();
    }

    private async Task LoadProfileAsync()
    {
        _loading = true;
        _savedProfile = await SettingsService.GetProfileAsync();
        ApplyProfile(_savedProfile);
        _loading = false;
    }

    private void ApplyProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;
    }

    private async Task SaveAsync()
    {
        var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        _message = "Profile saved successfully!";
    }

    private void DiscardChanges()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
        }
        _message = null;
    }
}

@namespace sv_61f065cf9e9049188e7418691eccd5b2.Components.Pages.Settings
@using sv_61f065cf9e9049188e7418691eccd5b2.Services
@inject ISettingsService SettingsService

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">Notification Preferences</h4>

        @if (_loading)
        {
            <div class="spinner-border" role="status"><span class="visually-hidden">Loading...</span></div>
        }
        else
        {
            @if (!string.IsNullOrEmpty(_message))
            {
                <div class="alert alert-success alert-dismissible fade show" role="alert">
                    @_message
                    <button type="button" class="btn-close" @onclick="() => _message = null"></button>
                </div>
            }

            <div class="mb-4">
                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" id="emailNotif" @bind="_emailNotifications" />
                    <label class="form-check-label" for="emailNotif">Email Notifications</label>
                </div>
                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" id="pushNotif" @bind="_pushNotifications" />
                    <label class="form-check-label" for="pushNotif">Push Notifications</label>
                </div>
                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="_weeklyDigest" />
                    <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
                </div>
            </div>

            <h5 class="mb-3">Muted Channels</h5>
            <div class="mb-4">
                @foreach (var channel in _channels)
                {
                    <div class="form-check mb-2">
                        <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                               checked="@_mutedChannels.Contains(channel)"
                               @onchange="e => ToggleMute(channel, (bool)e.Value!)" />
                        <label class="form-check-label" for="@($"ch-{channel}")">@channel</label>
                    </div>
                }
            </div>

            <button class="btn btn-primary" @onclick="SaveAsync">Save Preferences</button>
        }
    </div>
</div>

@code {
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<string> _channels = [];
    private HashSet<string> _mutedChannels = [];
    private string? _message;
    private bool _loading = true;

    private static readonly string[] AllChannels = ["general", "random", "off-topic", "announcements", "engineering", "design"];

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _mutedChannels = new HashSet<string>(prefs.MutedChannels);
        _channels = AllChannels.ToList();
        _loading = false;
    }

    private void ToggleMute(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _message = "Notification preferences saved!";
    }
}

@namespace sv_61f065cf9e9049188e7418691eccd5b2.Components.Pages.Settings
@using sv_61f065cf9e9049188e7418691eccd5b2.Services
@inject ISettingsService SettingsService

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">Security Settings</h4>

        @if (_loading)
        {
            <div class="spinner-border" role="status"><span class="visually-hidden">Loading...</span></div>
        }
        else
        {
            @if (!string.IsNullOrEmpty(_message))
            {
                <div class="alert @_messageClass alert-dismissible fade show" role="alert">
                    @_message
                    <button type="button" class="btn-close" @onclick="() => _message = null"></button>
                </div>
            }

            <!-- Change Password Panel -->
            <div class="card mb-4">
                <div class="card-header d-flex justify-content-between align-items-center"
                     style="cursor:pointer" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                    <span><strong>Change Password</strong></span>
                    <span>@(_passwordPanelOpen ? "▲" : "▼")</span>
                </div>
                @if (_passwordPanelOpen)
                {
                    <div class="card-body">
                        <div class="mb-3">
                            <label class="form-label">Current Password</label>
                            <input type="password" class="form-control" @bind="_currentPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">New Password</label>
                            <input type="password" class="form-control" @bind="_newPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Confirm New Password</label>
                            <input type="password" class="form-control" @bind="_confirmPassword" />
                        </div>
                        <button class="btn btn-warning" @onclick="ChangePasswordAsync">Update Password</button>
                        @if (_security?.LastPasswordChange is not null)
                        {
                            <p class="text-muted mt-2 mb-0">
                                Last changed: @_security.LastPasswordChange.Value.ToString("MMM dd, yyyy")
                            </p>
                        }
                    </div>
                }
            </div>

            <!-- Two-Factor Authentication -->
            <div class="card mb-4">
                <div class="card-body d-flex justify-content-between align-items-center">
                    <div>
                        <strong>Two-Factor Authentication</strong>
                        <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary") ms-2">
                            @(_twoFactorEnabled ? "Enabled" : "Disabled")
                        </span>
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" @bind="_twoFactorEnabled" />
                    </div>
                </div>
            </div>

            <!-- Active Sessions -->
            <div class="card">
                <div class="card-header"><strong>Active Sessions</strong></div>
                <div class="card-body p-0">
                    <div class="table-responsive">
                        <table class="table table-hover mb-0">
                            <thead>
                                <tr>
                                    <th>Device</th>
                                    <th>Location</th>
                                    <th>Last Active</th>
                                    <th></th>
                                </tr>
                            </thead>
                            <tbody>
                                @if (_sessions is not null)
                                {
                                    @foreach (var session in _sessions)
                                    {
                                        <tr>
                                            <td>@session.Device</td>
                                            <td>@session.Location</td>
                                            <td>@FormatLastActive(session.LastActive)</td>
                                            <td>
                                                @if (session.Id != _currentSessionId)
                                                {
                                                    <button class="btn btn-sm btn-outline-danger"
                                                            @onclick="() => ConfirmRevoke(session)">
                                                        Revoke
                                                    </button>
                                                }
                                                else
                                                {
                                                    <span class="badge bg-info">Current</span>
                                                }
                                            </td>
                                        </tr>
                                    }
                                }
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>

            <!-- Revoke Confirmation Dialog -->
            @if (_sessionToRevoke is not null)
            {
                <div class="modal d-block" tabindex="-1" style="background-color:rgba(0,0,0,0.5)">
                    <div class="modal-dialog modal-dialog-centered">
                        <div class="modal-content">
                            <div class="modal-header">
                                <h5 class="modal-title">Confirm Session Revocation</h5>
                                <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                            </div>
                            <div class="modal-body">
                                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                            </div>
                            <div class="modal-footer">
                                <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                <button class="btn btn-danger" @onclick="RevokeSessionAsync">Revoke Session</button>
                            </div>
                        </div>
                    </div>
                </div>
            }
        }
    </div>
</div>

@code {
    private SecuritySettings? _security;
    private List<ActiveSession>? _sessions;
    private bool _twoFactorEnabled;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _message;
    private string _messageClass = "alert-success";
    private bool _loading = true;
    private ActiveSession? _sessionToRevoke;

    // First session is treated as "current"
    private string? _currentSessionId;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        _security = await SettingsService.GetSecuritySettingsAsync();
        _sessions = _security.Sessions.ToList();
        _twoFactorEnabled = _security.TwoFactorEnabled;
        _currentSessionId = _sessions.FirstOrDefault()?.Id;
        _loading = false;
    }

    private async Task ChangePasswordAsync()
    {
        if (string.IsNullOrWhiteSpace(_newPassword) || _newPassword != _confirmPassword)
        {
            _message = "Passwords do not match or are empty.";
            _messageClass = "alert-danger";
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _message = "Password updated successfully!";
        _messageClass = "alert-success";
        _security = await SettingsService.GetSecuritySettingsAsync();
    }

    private void ConfirmRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }

    private async Task RevokeSessionAsync()
    {
        if (_sessionToRevoke is null) return;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
        _sessions = _sessions?.Where(s => s.Id != _sessionToRevoke.Id).ToList();
        _sessionToRevoke = null;
        _message = "Session revoked.";
        _messageClass = "alert-success";
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

@namespace sv_61f065cf9e9049188e7418691eccd5b2.Components.Pages.Settings
@using sv_61f065cf9e9049188e7418691eccd5b2.Services
@inject ISettingsService SettingsService

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">Appearance Settings</h4>

        @if (_loading)
        {
            <div class="spinner-border" role="status"><span class="visually-hidden">Loading...</span></div>
