toolArgs.file_text:
@namespace sv_61f065cf9e9049188e7418691eccd5b2.Components.Pages.Settings
@using sv_61f065cf9e9049188e7418691eccd5b2.Services
@inject ISettingsService SettingsService

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">Appearance Settings</h4>

        @if (_loading)
        {
            <div class="spinner-border" role="status"><span class="visually-hidden">Loading...</span></div>
        }
        else
        {
            @if (!string.IsNullOrEmpty(_message))
            {
                <div class="alert alert-success alert-dismissible fade show" role="alert">
                    @_message
                    <button type="button" class="btn-close" @onclick="() => _message = null"></button>
                </div>
            }

            <div class="row">
                <div class="col-md-7">
                    <!-- Theme -->
                    <div class="mb-4">
                        <h6>Theme</h6>
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            <div class="form-check form-check-inline">
                                <input class="form-check-input" type="radio" name="theme"
                                       id="@($"theme-{theme}")" value="@theme"
                                       checked="@(_theme == theme)"
                                       @onchange="() => _theme = theme" />
                                <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                            </div>
                        }
                    </div>

                    <!-- Font Size -->
                    <div class="mb-4">
                        <h6>Font Size</h6>
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            <div class="form-check form-check-inline">
                                <input class="form-check-input" type="radio" name="fontSize"
                                       id="@($"size-{size}")" value="@size"
                                       checked="@(_fontSize == size)"
                                       @onchange="() => _fontSize = size" />
                                <label class="form-check-label" for="@($"size-{size}")">@size</label>
                            </div>
                        }
                    </div>

                    <!-- Language -->
                    <div class="mb-4">
                        <h6>Language</h6>
                        <select class="form-select" style="max-width:250px" @bind="_language">
                            <option value="English">English</option>
                            <option value="Spanish">Spanish</option>
                            <option value="French">French</option>
                            <option value="German">German</option>
                            <option value="Japanese">Japanese</option>
                        </select>
                    </div>

                    <!-- Compact Mode -->
                    <div class="mb-4">
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                            <label class="form-check-label" for="compactMode">Compact Mode</label>
                        </div>
                    </div>

                    <button class="btn btn-primary" @onclick="SaveAsync">Save</button>
                </div>

                <!-- Live Preview -->
                <div class="col-md-5">
                    <h6>Preview</h6>
                    <div class="border rounded p-3 @PreviewBgClass" style="@PreviewStyle">
                        <h5 class="@PreviewTextClass" style="@PreviewFontStyle">Sample Heading</h5>
                        <p class="@PreviewTextClass" style="@PreviewFontStyle">
                            This is how your content will look with the selected settings.
                        </p>
                        <div class="d-flex gap-2 @(_compactMode ? "mt-1" : "mt-3")">
                            <span class="badge bg-primary">Tag</span>
                            <span class="badge bg-secondary">Label</span>
                        </div>
                        <p class="@PreviewTextClass mt-2 mb-0" style="@PreviewFontStyle">
                            <small>Language: @_language | @(_compactMode ? "Compact" : "Standard") layout</small>
                        </p>
                    </div>
                </div>
            </div>
        }
    </div>
</div>

@code {
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private string? _message;
    private bool _loading = true;

    private string PreviewBgClass => _theme switch
    {
        "Dark" => "bg-dark",
        _ => "bg-light"
    };

    private string PreviewTextClass => _theme switch
    {
        "Dark" => "text-light",
        _ => "text-dark"
    };

    private string PreviewStyle => _compactMode ? "padding: 0.5rem !important;" : "";

    private string PreviewFontStyle => _fontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.25rem;",
        _ => "font-size: 1rem;"
    };

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAsync()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _message = "Appearance settings saved!";
    }
}

